function localRead(k,d){try{return JSON.parse(localStorage.getItem(k)||JSON.stringify(d))}catch{return d}}
function toast(msg,type='info'){
  const text=String(msg??'');
  if(typeof window.showToast==='function' && window.showToast!==toast){
    try{return window.showToast(text,type)}catch{}
  }
  const el=document.getElementById('toast');
  if(!el){console[type==='error'?'error':'log'](text);return;}
  el.textContent=text;
  el.className='show '+type;
  el.setAttribute('role','status');
  el.hidden=false;
  clearTimeout(window.__angelToastTimer);
  window.__angelToastTimer=setTimeout(()=>{el.className='';el.hidden=true;},3500);
}
