async function api(path,opts={}){if(LOCAL_MODE)return localApi(path,opts);if(!backendUrl)throw new Error('Backend URL सेट नहीं है।');const headers={...(opts.body instanceof FormData?{}:{'Content-Type':'application/json'}),...(opts.headers||{})};const token=localStorage.getItem('angelAccessToken');if(token)headers.Authorization='Bearer '+token;const customerSession=localStorage.getItem('angelCustomerSession');if(customerSession)headers['X-Customer-Session']=customerSession;let r;try{r=await fetch(backendUrl.replace(/\/$/,'')+path,{...opts,headers})}catch(e){throw new Error('Backend से connection नहीं हो रहा। Render API URL या CORS settings जाँचें.')}let d={};try{d=await r.json()}catch{}if(r.status===401&&role==='admin'&&!path.startsWith('/api/auth/login')){showAdminLogin('Session expired or invalid');const e=new Error('Admin session expired/invalid है। कृपया login करें।');e.status=401;e.silent=true;throw e}if(!r.ok){const e=new Error(d.error||('Backend request failed ('+r.status+')'));e.status=r.status;throw e}return d}
