function go(page){
  const target=document.getElementById('page-'+page);
  if(!target)return;
  document.querySelectorAll('.page').forEach(x=>x.classList.remove('active-page'));
  target.classList.add('active-page');
  document.querySelectorAll('#nav [data-page],.side-bottom [data-page]').forEach(x=>x.classList.toggle('active',x.dataset.page===page));
  const crumb=document.getElementById('crumb'); if(crumb)crumb.textContent=titles[page]||page;
  try{localStorage.setItem('angelAdminPage',page)}catch{}
  loadPageData(page);
  if(page==='operations'&&window.angelLoadOps)window.angelLoadOps();
  if(page==='finance'&&window.angelLoadFinance)window.angelLoadFinance();
}
function bindAdminNavigation(){
  if(document.body?.dataset.panel!=='admin')return;
  const bind=()=>document.querySelectorAll('[data-page]').forEach(b=>{
    if(b.dataset.boundNav==='1')return;
    const page=b.dataset.page;
    if(!page)return;
    b.dataset.boundNav='1';
    b.addEventListener('click',e=>{e.preventDefault();go(page);if(page==='security')loadSecurityAudit(); if(window.closeAdminMobileMenu)window.closeAdminMobileMenu()});
  });
  bind();
  if(!window.__angelPageDelegation){
    window.__angelPageDelegation=true;
    document.addEventListener('click',e=>{
      const pageBtn=e.target.closest?.('[data-page]');
      if(pageBtn && document.body?.dataset.panel==='admin'){e.preventDefault();go(pageBtn.dataset.page);window.closeAdminMobileMenu?.();return;}
      const openBtn=e.target.closest?.('[data-open]');
      if(openBtn && document.body?.dataset.panel==='admin'){
        e.preventDefault();
        const page=openBtn.dataset.open;
        const name=openBtn.dataset.service;
        if(page==='detail' && name){
          const svc=services.find(x=>x[1]===name);
          if(svc){openPublicServiceDetails(svc);renderDetailPage(svc);$('#reqCat').value=svc[1];syncCustomerServiceControls();}
        }
        go(page);
      }
    });
  }
  const saved=localStorage.getItem('angelAdminPage');
  if(saved&&document.getElementById('page-'+saved))go(saved); else go('home');
}
async function verifyAdminSession(){const token=localStorage.getItem('angelAccessToken');if(!token)return false;try{await api('/api/tokens');currentUser={name:localStorage.getItem('angelStaffName')||'Admin',role:'admin'};$('#adminAuth')?.classList.add('hidden');$('#app')?.classList.remove('hidden');applyRoleAccess();go('admin');return true}catch(e){if(e?.status===401||e?.silent)return false;showAdminLogin();return false}}
