function serviceFromApi(x){
 const fallback=FALLBACK_SERVICES.find(v=>v[1]===x.category);
 return [fallback?.[0]||'◉',x.category,Array.isArray(x.services)?x.services.length:0,fallback?.[3]||'digital',Number(fallback?.[4]||0),fallback?.[5]||''];
}
async function loadServiceCatalog(){
 try{
   const d=await api('/api/services');
   const rows=Array.isArray(d.services)?d.services:[];
   if(!rows.length)throw new Error('Service catalog खाली है');
   backendServiceCatalog=rows;window.angelBackendServiceCatalog=rows;
   SERVICE_CATALOG_BY_CATEGORY=Object.fromEntries(rows.map(x=>[x.category,Array.isArray(x.services)?x.services:[]]));
   services=rows.map(serviceFromApi);
   return true;
 }catch(e){
   backendServiceCatalog=[];
   SERVICE_CATALOG_BY_CATEGORY={};
   services=FALLBACK_SERVICES;
   console.warn('Service catalog API unavailable; using audited fallback catalog',e?.message||e);
   return false;
 }
}
