function renderQueue(rows){const body=$('#queueTable');if(!body)return;body.innerHTML=(rows||[]).map((r,i)=>{const extra=r.status==='होल्ड'?`<small class="muted">${escapeHtml(r.hold_reason||'')} · ${r.hold_overdue?'OVERDUE':((r.hold_remaining_minutes??'—')+' min')}</small>`:r.status==='स्किप'?`<small class="muted">Reason: ${escapeHtml(r.skip_reason||'')}</small>`:'';return `<tr><td>${i+1}</td><td><b>${escapeHtml(r.token)}</b></td><td>${escapeHtml(r.service||'—')}</td><td>${escapeHtml(r.name||'—')}</td><td>${escapeHtml(r.staff_name||'—')}</td><td>${r.priority?'⭐':'—'}</td><td>${r.estimated_wait_minutes??'—'} min</td><td><span class="status-pill ${r.status==='पूर्ण'?'done':'pending'}">${escapeHtml(r.status)}</span>${extra}</td></tr>`}).join('')||'<tr><td colspan="8">आज कोई token नहीं है</td></tr>'}
function renderServiceQueues(queues){const box=$('#serviceQueueCards');if(!box)return;box.innerHTML=(queues||[]).map(q=>`<article class="service"><div class="icon">🎫</div><h3>${escapeHtml(q.service)}</h3><small>Waiting: ${q.waiting} · Completed: ${q.completed}</small><p class="muted">Current: <b>${escapeHtml(q.current||'—')}</b></p></article>`).join('')||'<div class="panel">कोई service-wise queue नहीं है।</div>'}
function renderLive(rows){const active=(rows||[]).find(x=>['बुलाया','प्रगति'].includes(x.status))||(rows||[]).find(x=>x.status==='लंबित')||(rows||[])[0];if(!active){$('#liveCurrent').textContent='—';$('#currentToken').textContent='—';$('#currentCustomer').textContent='कोई active token नहीं';$('#nextTokens').innerHTML='';return}$('#liveCurrent').textContent=active.token;$('#currentToken').textContent=active.token;$('#currentCustomer').textContent=(active.name||'ग्राहक')+' · '+active.service;$('#liveService').textContent='सेवा: '+active.service;$('#nextTokens').innerHTML=(rows||[]).filter(x=>x.id!==active.id&&x.status!=='पूर्ण'&&x.status!=='रद्द').slice(0,6).map(x=>`<b>${escapeHtml(x.token)}</b>` ).join('')}
async function loadTokens(){try{const d=await api('/api/tokens');const tokens=d.tokens||[];window.__angelTokenRows=tokens;renderQueue(tokens);renderServiceQueues(d.service_queues||[]);renderLive(tokens);const active=tokens.filter(x=>!['पूर्ण','रद्द','स्किप'].includes(x.status)).length;const waiting=tokens.filter(x=>x.status==='लंबित').length;const completed=tokens.filter(x=>x.status==='पूर्ण').length;const waits=tokens.filter(x=>Number.isFinite(Number(x.estimated_wait_minutes))).map(x=>Number(x.estimated_wait_minutes));if($('#tokenActiveCount'))$('#tokenActiveCount').textContent=active;if($('#tokenWaitingCount'))$('#tokenWaitingCount').textContent=waiting;if($('#tokenCompletedCount'))$('#tokenCompletedCount').textContent=completed;if($('#tokenAvgWait'))$('#tokenAvgWait').textContent=(waits.length?Math.round(waits.reduce((a,b)=>a+b,0)/waits.length):0)+' min';if($('#statTokens'))$('#statTokens').textContent=tokens.length;if($('#waitTime'))$('#waitTime').textContent=((d.current?.estimated_wait_minutes??tokens.find(x=>x.status==='लंबित')?.estimated_wait_minutes)??'—')+' मिनट';if(d.control_current){localStorage.setItem('angelCurrentTokenId',String(d.control_current.id));}window.dispatchEvent(new CustomEvent('angel:tokens-loaded',{detail:tokens}));}catch(e){toast(e.message)}}
function safeGet(key, fallback=''){try{return localStorage.getItem(key)??fallback}catch{return fallback}}
function safeSet(key,value){try{localStorage.setItem(key,value);return true}catch{return false}}
function readJson(key,fallback){try{const raw=safeGet(key,'');return raw?JSON.parse(raw):fallback}catch{return fallback}}
function writeJson(key,value){safeSet(key,JSON.stringify(value))}
function getToday(){return new Date().toLocaleDateString('en-CA',{timeZone:'Asia/Kolkata'})}
function populateTokenServices(preferred=''){
 const sel=$('#tokenService'); if(!sel)return;
 const current=preferred||sel.value||'';
 const names=[];
 Object.values(SERVICE_INFO||{}).forEach(info=>(info.services||[]).forEach(sub=>{if(sub?.name&&!names.includes(sub.name))names.push(sub.name)}));
 // keep the selected category-level service if an older flow supplied it
 services.forEach(x=>{if(x?.[1]&&!names.includes(x[1]))names.push(x[1])});
 sel.innerHTML='<option value="">सेवा चुनें</option>'+names.map(n=>`<option value="${escapeHtml(n)}">${escapeHtml(n)}</option>` ).join('');
 if(current){const exists=[...sel.options].some(o=>o.value===current);if(!exists){const o=document.createElement('option');o.value=current;o.textContent=current;sel.appendChild(o)}sel.value=current;}
}
async function issueLocalToken(){
 const btn=$('#issueToken'); if(btn?.dataset.busy==='1')return; if(btn)btn.dataset.busy='1';
 try{const service=(($('#tokenService')?.value||'').trim()||($('#reqService')?.value||'').trim());const name=(($('#tokenName')?.value||'').trim()||currentCustomer?.name||'').trim();const mobile=(($('#tokenMobile')?.value||'').trim()||currentCustomer?.mobile||'').trim();if(!service)return toast('पहले सेवा चुनें');if(!name)return toast('ग्राहक का नाम भरें');if(!/^\d{10}$/.test(mobile))return toast('सही 10 digit मोबाइल भरें');const payment_id=Number(localStorage.getItem('angelPaymentId')||0);let d;if(role==='customer'){if(!payment_id)return toast('पहले payment submit करें');d=await api('/api/customer/tokens',{method:'POST',body:JSON.stringify({service,name,mobile,payment_id})})}else{const payment_id=Number($('#tokenPaymentId')?.value||localStorage.getItem('angelPaymentId')||0);if(!payment_id)return toast('Verified Payment ID जरूरी है');d=await api('/api/tokens',{method:'POST',body:JSON.stringify({action:'issue',service,name,mobile,payment_id})})}currentCustomer={name,mobile};writeJson('angelCustomerLocal',currentCustomer);safeSet('angelCustomerLogin','1');updateCustomerButton();fillCustomer(currentCustomer);$('#tokenNumber').textContent=d.token;$('#ticketService').textContent='सेवा: '+service;await loadTokens();toast('नया token '+d.token+' जारी हुआ')}catch(e){toast(e.message)}finally{if(btn)setTimeout(()=>btn.dataset.busy='0',350)}}
$('#issueToken').onclick=issueLocalToken;
document.addEventListener('click',e=>{const btn=e.target.closest?.('#issueToken');if(btn){e.preventDefault();issueLocalToken()}},true);

