async function tokenAction(action,extra={}){try{const q=await api('/api/tokens');const storedId=Number(localStorage.getItem('angelCurrentTokenId'))||null;let id=storedId||Number(q.current?.id)||null;if(action!=='next'&&!id){const label=$('#currentToken')?.textContent?.trim();const found=(q.tokens||[]).find(t=>t.token===label);id=Number(found?.id)||null;}if(action!=='next'&&!id)throw new Error('Current token नहीं मिला');const payload=action==='next'?{action}:{action,id,...extra};const d=await api('/api/tokens',{method:'POST',body:JSON.stringify(payload)});if(d?.id!=null)localStorage.setItem('angelCurrentTokenId',String(d.id));await loadTokens();toast('Token '+d.token+' — '+d.status)}catch(e){toast(e.message)}}
function askReason(title){const r=prompt(title+'\n\nReason लिखें:');if(r===null)return null;if(!r.trim()){toast('Reason जरूरी है');return null}return r.trim()}
function holdToken(){const reason=askReason('काम Pending / Hold');if(!reason)return;const owner=(prompt('Delay किसकी वजह से है? customer / operator / portal / department / other','customer')||'').trim().toLowerCase();if(!['customer','operator','portal','department','other'].includes(owner)){toast('Valid delay owner चुनें');return}const mins=Number(prompt('Expected delay कितने मिनट?','15'));if(!Number.isInteger(mins)||mins<1||mins>1440){toast('1 से 1440 मिनट चुनें');return}tokenAction('hold',{reason,owner,delay_minutes:mins})}
function skipToken(){const reason=askReason('Token Skip');if(reason)tokenAction('skip',{reason})}
function extendHold(){const mins=Number(prompt('और कितने मिनट बढ़ाना है?','15'));if(!Number.isInteger(mins)||mins<1||mins>1440){toast('1 से 1440 मिनट चुनें');return}const reason=askReason('Delay Extension');if(reason)tokenAction('extend_hold',{delay_minutes:mins,reason})}
async function selectedTokenRecord(){const q=await api('/api/tokens');const storedId=Number(localStorage.getItem('angelCurrentTokenId'))||null;return (q.tokens||[]).find(t=>Number(t.id)===storedId)||q.current||null}
async function chooseStaff(){const d=await api('/api/staff');const staff=(d.staff||[]).filter(x=>x.status==='active');if(!staff.length)throw new Error('कोई active staff उपलब्ध नहीं है');const list=staff.map((x,i)=>`${i+1}. ${x.name} (${x.employee_id})`).join('\n');const n=Number(prompt('Staff चुनें:\n'+list+'\n\nNumber:','1'));if(!Number.isInteger(n)||n<1||n>staff.length)throw new Error('Valid staff चुनें');return staff[n-1]}
async function assignCurrentToken(action='assign'){try{const t=await selectedTokenRecord();if(!t)throw new Error('Current token नहीं मिला');const st=await chooseStaff();const reason=action==='transfer'?askReason('Transfer Reason'):'';if(action==='transfer'&&!reason)return;await api('/api/tokens',{method:'POST',body:JSON.stringify({action, id:t.id, staff_id:st.staff_id, from_staff_id:t.staff_id||null, reason:reason||''})});await loadTokens();toast((action==='transfer'?'Token transfer':'Staff assignment')+' सफल')}catch(e){toast(e.message)}}
async function togglePriority(){try{const t=await selectedTokenRecord();if(!t)throw new Error('Current token नहीं मिला');const enabled=!Boolean(t.priority);const reason=enabled?askReason('Priority Token'):'';if(enabled&&!reason)return;await api('/api/tokens',{method:'POST',body:JSON.stringify({action:'priority',id:t.id,enabled,reason:reason||''})});await loadTokens();toast(enabled?'Priority Token set':'Priority हटाई गई')}catch(e){toast(e.message)}}
async function cancelCurrentToken(){try{const t=await selectedTokenRecord();if(!t)throw new Error('Current token नहीं मिला');const reason=askReason('Token Cancel');if(!reason)return;await api('/api/tokens',{method:'POST',body:JSON.stringify({action:'cancel',id:t.id,reason})});await loadTokens();toast('Token cancelled')}catch(e){toast(e.message)}}
async function notifyCurrentToken(){try{const t=await selectedTokenRecord();if(!t)throw new Error('Current token नहीं मिला');const message=prompt('Customer notification message:',`Token ${t.token}: आपकी service queue में update है।`);if(!message?.trim())return;await api('/api/tokens',{method:'POST',body:JSON.stringify({action:'notify',id:t.id,title:'Token Update',message:message.trim()})});toast('Notification record बनाया गया')}catch(e){toast(e.message)}}
