$('#payMethod').onchange=()=>{$('#utrWrap').style.display=$('#payMethod').value==='Cash'?'none':'';if($('#payProofWrap'))$('#payProofWrap').style.display=$('#payMethod').value==='Cash'?'none':''};$('#payMethod').dispatchEvent(new Event('change'));$('#savePayment').onclick=async()=>{try{const method=$('#payMethod').value,service=$('#payService')?.value?.trim()||'',file=$('#payProof')?.files?.[0];if(method!=='Cash'&&(!$('#payUtr').value.trim()||!file))return toast('UPI/Bank payment में UTR और Screenshot/Proof दोनों दें');let proof_data='';if(file){if(!/^image\/(png|jpeg|webp)$/.test(file.type)||file.size>5*1024*1024)return toast('Proof PNG/JPG/WEBP और अधिकतम 5 MB होना चाहिए');proof_data=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(new Error('Proof file read नहीं हो सकी'));r.readAsDataURL(file)})}const payload={service,name:$('#payName').value.trim(),mobile:$('#payMobile').value.trim(),application_id:Number($('#payApplication').value||0)||null,amount:Number($('#payAmount').value||0),method,utr:$('#payUtr').value.trim(),payment_date:$('#payDate').value,proof_data};if(!payload.service)return toast('Service चुनें');if(!payload.name||!/^[0-9]{10}$/.test(payload.mobile))return toast('नाम और 10 digit mobile भरें');if(!payload.amount)return toast('राशि भरें');if(method!=='Cash'&&(!payload.utr||!proof_data))return toast('UPI/Bank payment में UTR और Screenshot/Proof दोनों दें');const d=await api('/api/payments',{method:'POST',body:JSON.stringify(payload)});toast(d.status==='Verified'?'Cash payment verified और receipt तैयार':'Payment दर्ज: proof verify होने तक Pending रहेगा');$('#paymentModal').classList.add('hidden');if($('#payProof'))$('#payProof').value='';loadPayments()}catch(e){toast(e.message)}};
