async function uploadFiles(aid){
 const files=[...($('#fileInput')?.files||[])];if(!files.length)return;
 if(files.length>5)throw new Error('एक application में अधिकतम 5 documents upload कर सकते हैं');
 const allowed=new Set(['application/pdf','image/jpeg','image/png','image/webp']);
 let total=0;
 const payload=[];
 for(const f of files){
   if(!allowed.has(f.type))throw new Error(f.name+' का file type supported नहीं है');
   if(f.size>5*1024*1024)throw new Error(f.name+' 5 MB से बड़ा है');
   total+=f.size;if(total>10*1024*1024)throw new Error('सभी documents का कुल size 10 MB से अधिक है');
   const data=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(String(r.result||''));r.onerror=()=>reject(new Error('File read failed: '+f.name));r.readAsDataURL(f)});
   payload.push({name:f.name,mime_type:f.type,data});
 }
 await api('/api/documents',{method:'POST',body:JSON.stringify({application_id:aid,files:payload})});
 toast(files.length+' document(s) server पर सुरक्षित upload हो गए।');
}
